    def findValidPair(self, s: str) -> str:
        counts = {}
        for ch in s:
            counts[ch] = counts.get(ch, 0) + 1

        for i in range(len(s) - 1):
            a, b = s[i], s[i + 1]
            if a != b and counts.get(a, 0) == int(a) and counts.get(b, 0) == int(b):
