class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        letters = [ord(c) - 97 for c in s]
        dp = [[[0] * (k + 1) for _ in range(n)] for __ in range(n)]

        for i in range(n):
            for r in range(k + 1):
                dp[i][i][r] = 1

        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                d = abs(letters[i] - letters[j])
                if d > 13:
                    d = 26 - d
                row_ij = dp[i][j]
                row_next_j = dp[i + 1][j]
                row_i_prev = dp[i][j - 1]
                row_inner = dp[i + 1][j - 1]
                for r in range(k + 1):
                    best = row_next_j[r]
                    if row_i_prev[r] > best:
                        best = row_i_prev[r]
                    if r >= d:
                        val = row_inner[r - d] + 2
                        if val > best:
                            best = val
                    row_ij[r] = best

        return dp[0][n - 1][k]

