def solve():
    s = sys.stdin.readline().strip()
    n = len(s)

    # Odd Manacher: d1[i] = max k such that s[i-k+1:i+k] is palindrome
    d1 = [0] * n
    l, r = 0, -1
    for i in range(n):
        k = 1 if i > r else min(d1[l + r - i], r - i + 1)
        while i - k >= 0 and i + k < n and s[i - k] == s[i + k]:
            k += 1
        d1[i] = k
        if i + k - 1 > r:
            l = i - k + 1
            r = i + k - 1

    # Even Manacher: d2[i] = max k such that s[i-k:i+k] is palindrome (center between i-1 and i)
    d2 = [0] * (n + 1)
    l, r = 0, -1
    for i in range(n + 1):
        k = 0 if i > r else min(d2[l + r - i + 1], r - i + 1)
        while i - k - 1 >= 0 and i + k < n and s[i - k - 1] == s[i + k]:
            k += 1
        d2[i] = k
        if i + k - 1 > r:
            l = i - k
            r = i + k - 1

    best = n  # smallest x; x = n-1 always exists (single-char suffix)
    for i in range(n):
        k = n - i
        if k >= 1 and d1[i] >= k:
            x = 2 * i - n + 1
            if x >= 0 and x < best:
                best = x
    for i in range(1, n + 1):
        k = n - i
        if k >= 1 and d2[i] >= k:
            x = 2 * i - n
            if x >= 0 and x < best:
                best = x

    sys.stdout.write(s + s[:best][::-1])

