    cur_max = []
    for g in groups:
        if use_np:
            dp = np.zeros(X + 1, dtype=np.int64)
            for a, c in g:
                if c > X:
                    continue
                contrib = dp[:X + 1 - c] + a
                dp[c:] = np.maximum(dp[c:], contrib)
            # make dp nondecreasing (it already is, but ensure)
            # dp is max intake with <= calories; keep as is
            dps.append(dp)
            cur_max.append(min(X, sum(c for _, c in g if c <= X)))
        else:
            dp = [0] * (X + 1)
            cur = 0
            for a, c in g:
                if c > X:
                    continue
                new_max = cur + c
                if new_max > X:
                    new_max = X
                for x in range(new_max, c - 1, -1):
                    v = dp[x - c] + a
                    if v > dp[x]:
                        dp[x] = v
                cur = new_max
            # propagate max forward so dp[x] = max intake with <= x calories
            for x in range(1, cur + 1):
                if dp[x] < dp[x - 1]:
                    dp[x] = dp[x - 1]
            dps.append(dp)
            cur_max.append(cur)

