        if T == 0:
            return 0
        dp = dps[i]
        cur = cur_max[i]
        lo, hi = 0, cur
        while lo < hi:
            mid = (lo + hi) // 2
            if dp[mid] >= T:
                hi = mid
            else:
                lo = mid + 1
        if dp[lo] >= T:
            return lo
        return None

    def feasible(T):
        s = 0
        for i in range(3):
