from functools import lru_cache

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        total_odd = (n + 1) // 2
        total_even = n // 2

        # Pattern starting with odd
        total = fact[total_odd] * fact[total_even]
        # Pattern starting with even (only feasible for even n)
        if n % 2 == 0:
            total += fact[total_odd] * fact[total_even]

        if k > total:
            return []

        @lru_cache(maxsize=None)
        def ways(i, r_odd, r_even, last_parity):
            # ways to fill positions i..n-1 with r_odd odds and r_even evens
            # last_parity: 1 = odd, 0 = even, -1 = start of permutation
            m = n - i
            if m == 0:
                return 1 if (r_odd == 0 and r_even == 0) else 0
            res = 0
            if last_parity == -1:
                start_parities = (1, 0)
            else:
                start_parities = (1 - last_parity,)
            for p in start_parities:
                odd_pos = 0
                even_pos = 0
                cur = p
                for _ in range(m):
                    if cur == 1:
                        odd_pos += 1
                    else:
                        even_pos += 1
                    cur = 1 - cur
                if odd_pos == r_odd and even_pos == r_even:
                    res += fact[r_odd] * fact[r_even]
            return res

        used = [False] * (n + 1)
        res = []
        r_odd, r_even = total_odd, total_even
        last_parity = -1

        for i in range(n):
            for v in range(1, n + 1):
                if used[v]:
                    continue
                par = v & 1
                if last_parity != -1 and par == last_parity:
                    continue
                if par == 1:
                    if r_odd == 0:
                        continue
                    nr_odd, nr_even = r_odd - 1, r_even
                else:
                    if r_even == 0:
                        continue
                    nr_odd, nr_even = r_odd, r_even - 1
                w = ways(i + 1, nr_odd, nr_even, par)
                if k > w:
                    k -= w
                    continue
                # place v
                res.append(v)
                used[v] = True
                r_odd, r_even = nr_odd, nr_even
                last_parity = par
                break

        return res
